//! FORM enctype and encoding reflect one exact native content attribute.
use super::*;
const URL:&str="application/x-www-form-urlencoded";
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://form-enctype.test/submit><input id=area name=q value=Seed></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-enctype.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_enctype_canonical_aliases_known_keywords_once_and_raw_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form');for(var key of ['enctype','encoding']){var a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,key);if(!a||!a.enumerable||!a.configurable||a.get.name!=='get '+key||a.set.name!=='set '+key||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,key)||x[key]!=='application/x-www-form-urlencoded')throw 'canonical alias';}var calls=0;x.encoding={toString:function(){calls++;return 'MuLtiPart/Form-Data';},valueOf:function(){throw 'hint';}};if(calls!==1||x.enctype!=='multipart/form-data'||x.encoding!==x.enctype||x.getAttributeNS(null,'enctype')!=='MuLtiPart/Form-Data'||x.getAttributeNS(null,'encoding')!==null)throw 'same content attribute';x.enctype='TEXT/PLAIN';if(x.encoding!=='text/plain')throw 'plain';x.encoding=' text/plain ';if(x.enctype!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'enctype')!==' text/plain ')throw 'no trim';x.enctype='A\ud800Z';if(x.encoding!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'enctype')!=='A\ud800Z')throw 'raw';x.encoding=null;if(x.enctype!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'enctype')!=='null')throw 'null';x.enctype=undefined;if(x.encoding!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'enctype')!=='undefined')throw 'undefined';"#);}
#[test]
fn form_enctype_inert_exact_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','enctype','text/plain');x.setAttributeNS(null,'ENCTYPE','text/plain');x.setAttributeNS(null,'encoding','text/plain');if(x.enctype!=='application/x-www-form-urlencoded'||x.encoding!==x.enctype)throw 'exact attribute';x.encoding='MULTIPART/FORM-DATA';var copy=x.cloneNode(false);copy.enctype='TEXT/PLAIN';if(x.enctype!=='multipart/form-data'||copy.encoding!=='text/plain'||x.getAttributeNS(null,'enctype')!=='MULTIPART/FORM-DATA'||copy.getAttributeNS(null,'enctype')!=='TEXT/PLAIN')throw 'independent';");}
#[test]
fn form_enctype_native_urlencoded_and_preserved_unsupported_post_refusal(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://form-enctype.test/source",&crate::navigation::Location::home()).unwrap();for key in ["enctype","encoding"]{for raw in ["MULTIPART/FORM-DATA","TEXT/PLAIN"]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('form');x.{key}='{raw}';"));let before=format!("{:?}",d.nodes);let error=f.submit_request(&d,owner,None,&l,&l).err().unwrap();assert!(error.contains("multipart and text/plain forms are not implemented"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}for raw in [URL,"invalid"," text/plain "]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.{key}='{raw}';if(x.enctype!=='{URL}'||x.encoding!=='{URL}')throw 'fallback';"));let result=f.submit_request(&d,owner,None,&l,&l).unwrap();let crate::http::Request::FormPost{body,..}=result.request else{panic!("POST")};assert_eq!(body,b"q=Seed");}}}

#[test]
fn form_enctype_authority_brands_and_abrupt_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'enctype'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'application/x-www-form-urlencoded';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.enctype={toString:function(){calls++;x.enctype='multipart/form-data';return ' EMAIL ';}};if(calls!==1||x.enctype!=='application/x-www-form-urlencoded')throw 'outer conversion';var marker={};try{x.enctype={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.enctype!=='application/x-www-form-urlencoded'||x.getAttribute('data-side')!=='kept')throw 'abrupt state';Object.defineProperty(P,'enctype',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.enctype='override';a.set.call(x,'APPLICATION/X-WWW-FORM-URLENCODED');if(x.enctype!=='author'||a.get.call(x)!=='application/x-www-form-urlencoded')throw 'saved authority';delete P.enctype;if(x.enctype!==undefined)throw 'hidden member';Object.defineProperty(P,'enctype',a);var C=HTMLFormElement;delete window.HTMLFormElement;if(!(x instanceof C)||a.get.call(x)!=='application/x-www-form-urlencoded')throw 'saved constructor';");}
#[test]
fn form_enctype_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'enctype'),calls=0;if(a.get.call(x)!=='application/x-www-form-urlencoded')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-enctype.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'application/x-www-form-urlencoded';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-enctype.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'APPLICATION/X-WWW-FORM-URLENCODED');if(x.enctype!=='application/x-www-form-urlencoded')throw 'fresh recovery';");}

#[test]
fn form_enctype_named_control_precedence_preserves_saved_accessor_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'enctype');n.setAttribute('name','enctype');if(x.enctype!==n)throw 'named control precedence';var calls=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,{toString:function(){calls++;return 'MULTIPART/FORM-DATA';}});var records=watch.takeRecords();if(calls!==1||records.length!==1||records[0].attributeName!=='enctype'||x.enctype!==n||a.get.call(x)!=='multipart/form-data'||x.getAttributeNS(null,'enctype')!=='MULTIPART/FORM-DATA')throw 'saved authority';a.set.call(x,'multipart/form-data\\ud800');if(a.get.call(x)!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'enctype')!=='multipart/form-data\\ud800')throw 'named raw setter';a.set.call(x,'MULTIPART/FORM-DATA');n.setAttribute('name','q');if(x.enctype!=='multipart/form-data')throw 'live named removal';");}
#[test]
fn form_enctype_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.enctype='multipart/form-data';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_enctype_get(object).map(|_|())}else{bridge.form_enctype_set(object,&Value::String("growing-unknown-method-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.enctype='APPLICATION/X-WWW-FORM-URLENCODED';if(x.enctype!=='application/x-www-form-urlencoded'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_enctype_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.enctype='application/x-www-form-urlencoded';var attribute=x.getAttributeNodeNS(null,'enctype'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['enctype']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('enctype','MULTIPART/FORM-DATA');","x.setAttributeNS(null,'enctype','MULTIPART/FORM-DATA');","attribute.value='MULTIPART/FORM-DATA';","attribute.nodeValue='MULTIPART/FORM-DATA';","attribute.textContent='MULTIPART/FORM-DATA';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.enctype='application/x-www-form-urlencoded';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.enctype!=='multipart/form-data'||x.getAttributeNodeNS(null,'enctype')!==attribute||records.length!==1||records[0].oldValue!=='application/x-www-form-urlencoded'||records[0].attributeName!=='enctype'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('enctype');replacement.value='multipart/form-data\ud800';x.setAttributeNodeNS(replacement);if(x.enctype!=='application/x-www-form-urlencoded'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='multipart/form-data\ud800')throw 'raw attribute replacement';"#);}

#[test]
fn form_enctype_encoding_saved_alias_masks_and_conversion_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'encoding'),b=Object.getOwnPropertyDescriptor(P,'enctype');n.setAttribute('name','encoding');if(x.encoding!==n)throw 'alias mask';var calls=0;a.set.call(x,{toString:function(){calls++;return 'TEXT/PLAIN';}});if(calls!==1||x.encoding!==n||a.get.call(x)!=='text/plain'||x.enctype!=='text/plain')throw 'saved alias';n.setAttribute('name','enctype');if(x.enctype!==n||x.encoding!=='text/plain')throw 'independent mask';b.set.call(x,'MULTIPART/FORM-DATA');if(x.encoding!=='multipart/form-data'||b.get.call(x)!=='multipart/form-data')throw 'saved primary';n.setAttribute('name','q');Object.defineProperty(P,'encoding',{get:function(){return 'author';},configurable:true});a.set.call(x,'TEXT/PLAIN');if(x.encoding!=='author'||x.enctype!=='text/plain'||a.get.call(x)!=='text/plain')throw 'saved prototype alias';Object.defineProperty(P,'encoding',a);");}
